D={
81001:("Posse com 's","Para dizer **de quem** é algo, use **'s**: *my mother{{'s}} cousin*. Com plural em -s, só o apóstrofo: *my grandparents{{'}} house*.",[("This is my {{mother's}} cousin.","Este é o primo da minha mãe."),("It is my {{grandparents'}} house.","É a casa dos meus avós."),("{{Whose}} house is this?","De quem é esta casa?"),("It's {{Tom's}}, not {{Kim's}}.","É do Tom, não da Kim.")],"Como se diz “a casa dos meus avós”?",["my grandparents' house","my grandparent's houses","my house grandparents"],0,"Avós é plural em -s, então só entra o apóstrofo depois do s."),
81002:("Hábitos com every","Para tradições, use o **present simple** com *every*. Com he/she/it, o verbo ganha **-s**: *Dad light{{s}} a candle*.",[("We have dinner {{every}} Friday.","Jantamos toda sexta."),("Dad {{lights}} a candle every night.","O papai acende uma vela toda noite."),("We sing the same song {{every year}}.","Cantamos a mesma canção todo ano."),("My sister {{comes}} home for the holidays.","Minha irmã volta para casa nos feriados.")],"Qual frase está certa?",["Mom bake a cake every year.","Mom bakes a cake every year.","Mom baking a cake every year."],1,"Com Mom (= she), o verbo no present simple leva -s: bakes."),
81003:("He/she + verbo com -s","Ao descrever um amigo, o verbo leva **-s** com he/she. Na negativa, use **doesn't** + verbo base: *He doesn't tell secrets*.",[("He {{helps}} me with homework.","Ele me ajuda com a lição."),("She {{laughs}} at my jokes.","Ela ri das minhas piadas."),("He {{loves}} adventures.","Ele adora aventuras."),("He {{doesn't tell}} my secrets.","Ele não conta meus segredos.")],"Complete: “She ___ my secret.”",["don't tell","doesn't tells","doesn't tell"],2,"Depois de doesn't o verbo volta ao básico: tell, sem -s."),
81004:("be + adjetivo","Para descrever o jeito de alguém: **is/are + adjetivo**. Para reforçar, use *very* ou *a little*: *very funny, a little shy*.",[("Emma {{is}} kind.","A Emma é gentil."),("Mia is {{a little}} shy.","A Mia é um pouco tímida."),("Tom is {{very}} funny.","O Tom é muito engraçado."),("They {{are}} honest and smart.","Eles são honestos e inteligentes.")],"Como dizer “um pouco tímido”?",["very shy","a little shy","shy a little"],1,"A little vem antes do adjetivo e suaviza: a little shy."),
81005:("Datas com ordinais","Para datas, use **ordinais**: *first, second, third, fourth…* *It's May 1st* lê-se *May the first*.",[("When is {{your birthday}}?","Quando é o seu aniversário?"),("It's the {{first}} of May.","É 1º de maio."),("My party is on the {{second}} of June.","Minha festa é em 2 de junho."),("Her birthday is on the {{third}} of July.","O aniversário dela é em 3 de julho.")],"Como se lê “June 2nd”?",["June two","June the second","June twice"],1,"Na data, usa-se o ordinal: the second."),
81006:("be going to para planos","Para planos, use **am/is/are going to** + verbo base: *I'm going to bake a cake*. Na negativa: *aren't going to*.",[("I'm {{going to bake}} a cake.","Vou assar um bolo."),("Mia {{is going to send}} an invitation.","A Mia vai mandar um convite."),("We {{aren't going to be}} late.","Não vamos nos atrasar."),("{{Who is going to}} bring the playlist?","Quem vai trazer a playlist?")],"Qual frase fala de um plano?",["I baked a cake.","I'm going to bake a cake.","I bake cakes."],1,"Be going to + verbo base mostra um plano para o futuro."),
81007:("was/were born","Para dizer onde e quando nasceu: **was born** (I, he, she) e **were born** (you, we, they).",[("I {{was born}} in Recife.","Nasci em Recife."),("My parents {{were born}} in 1970.","Meus pais nasceram em 1970."),("{{Where were you born}}?","Onde você nasceu?"),("She {{was born}} in a small hospital.","Ela nasceu num hospital pequeno.")],"Complete: “My parents ___ born in Italy.”",["was","were","are"],1,"Parents é plural, então were. E nasceu é sempre passado."),
920001:("Passado regular com -ed","No passado regular, acrescente **-ed**: *visit → visited*. Na pergunta e na negativa, use **did** e volte ao verbo base: *Did you visit…?*",[("We {{walked}} in the park.","Caminhamos no parque."),("I {{visited}} the museum yesterday.","Visitei o museu ontem."),("{{Did you visit}} the tower?","Você visitou a torre?"),("No, I {{didn't visit}} it.","Não, eu não a visitei.")],"Qual pergunta está certa?",["Did you visited it?","Did you visit it?","You did visit it?"],1,"Depois de did o verbo fica no básico: visit."),
81008:("Crescer e se mudar","O passado de *grow up* é **grew up**; o de *move* é **moved**. Para perguntar: **Where did you grow up?**",[("I {{grew up}} in a small town.","Cresci numa cidade pequena."),("We {{moved}} to a big city.","Nos mudamos para uma cidade grande."),("{{Where did you grow up}}?","Onde você cresceu?"),("It was quiet, and I loved it.","Era tranquilo, e eu adorava.")],"Qual é o passado de “grow up”?",["growed up","grew up","grown up"],1,"Grow é irregular: grew up no passado."),
81009:("Línguas e habilidade","*Speak* para línguas, **good at** para habilidade e **fluent in** para falar bem: *He is fluent in French*.",[("I {{speak}} two languages.","Falo dois idiomas."),("He is {{fluent in}} French.","Ele é fluente em francês."),("She is {{good at}} English.","Ela é boa em inglês."),("Portuguese is my {{native}} language.","O português é minha língua nativa.")],"Como dizer “fluente em espanhol”?",["fluent on Spanish","fluent in Spanish","fluent at Spanish"],1,"Com fluent, usa-se a preposição in."),
81010:("Cometer erros","Em inglês, erro se **faz**: *make a mistake*. Para pedir ajuda: **Can you correct me?** Para melhorar: *practice every day*.",[("Everyone {{makes a mistake}}.","Todo mundo comete um erro."),("I {{practice}} every day.","Eu pratico todo dia."),("{{Can you correct me}}, please?","Você pode me corrigir, por favor?"),("My English is getting {{better}}.","Meu inglês está ficando melhor.")],"Qual verbo combina com “a mistake”?",["do","make","say"],1,"A combinação natural é make a mistake."),
81011:("like/love + -ing","Depois de *love, like, enjoy*, use o verbo com **-ing**: *I love painting*.",[("I {{love painting}}.","Adoro pintar."),("She {{enjoys cooking}}.","Ela gosta de cozinhar."),("We {{like hiking}} on Sundays.","Gostamos de fazer trilhas aos domingos."),("Do you {{enjoy reading}}?","Você gosta de ler?")],"Qual frase está certa?",["I enjoy to swim.","I enjoy swimming.","I enjoy swim."],1,"Depois de enjoy, o verbo vai para a forma -ing."),
81012:("want to + verbo","Para dizer o que quer fazer: **want to** + verbo. Com he/she: **wants to**.",[("I {{want to join}} the club.","Quero entrar no clube."),("Leo {{wants to come}} on Friday.","O Leo quer vir na sexta."),("{{Do you want to}} be a member?","Você quer ser sócio?"),("Is there a {{fee}}? No, it's free.","Tem taxa? Não, é grátis.")],"Complete: “Leo ___ to join us.”",["want","wants","wanting"],1,"Leo = he, então wants."),
81013:("be going to + plano","Plano = **am/is/are going to** + verbo base. *I am going to relax. We are going to see a movie.*",[("I {{am going to relax}} at home.","Vou relaxar em casa."),("We {{are going to have}} a picnic.","Vamos fazer um piquenique."),("{{What is your plan}} for Saturday?","Qual é o seu plano para sábado?"),("She {{is going to see}} a movie.","Ela vai ver um filme.")],"Como perguntar “Qual é o seu plano?”",["What is your plan?","What are plan you?","Which your plan is?"],0,"What is your plan? é a pergunta direta."),
81014:("have fun / enjoy","Diversão se **tem**: *have fun*. *Enjoy* pede objeto: *We enjoy the music*. Para convidar: **Let's** + verbo.",[("We {{have a lot of fun}}.","Nós nos divertimos muito."),("{{Let's play}} a game!","Vamos jogar um jogo!"),("I {{love}} this music.","Adoro esta música."),("Let's dance {{again}}, together!","Vamos dançar de novo, juntos!")],"Como convidar alguém para dançar?",["Let's dance!","We dancing!","Dance let's!"],0,"Let's + verbo é o convite natural."),
920002:("Passado irregular","Verbos irregulares têm **forma própria** no passado: *go → went, see → saw*. Pergunta: **Where did you go?**",[("I {{went}} to a village.","Fui a um vilarejo."),("I {{saw}} a rainbow.","Vi um arco-íris."),("{{Where did you go}} last summer?","Aonde você foi no verão passado?"),("We {{took}} lots of photos.","Tiramos muitas fotos.")],"Qual é o passado de “see”?",["seed","saw","seen"],1,"See é irregular: saw."),
81015:("Aparência","Descreva com **be + adjetivo** (*She is tall*), partes do rosto com **have** (*big eyes*) e roupa com **wears**.",[("She {{is}} young and beautiful.","Ela é jovem e bonita."),("She {{has}} big eyes.","Ela tem olhos grandes."),("She {{wears}} a pearl earring.","Ela usa um brinco de pérola."),("He is {{tall}} and thin.","Ele é alto e magro.")],"Complete: “He ___ short hair.”",["is","has","wears"],1,"Cabelo é parte do corpo: has short hair."),
81016:("What does he look like?","Para pedir a aparência: **What does he look like?** Resposta: *He has short hair. He wears glasses.*",[("{{What does he look like}}?","Como ele é?"),("He {{has short hair}}.","Ele tem cabelo curto."),("He {{wears glasses}} and a hat.","Ele usa óculos e chapéu."),("He is {{next to}} the fountain.","Ele está ao lado da fonte.")],"“What does she look like?” pergunta sobre…",["a aparência","a idade","o endereço"],0,"Look like pergunta como a pessoa é fisicamente."),
81017:("very / too / a little","*Very* = muito. *A little* = um pouco. **Too** = demais, mais do que o bom: *He is too lazy to run*.",[("He is {{very}} funny.","Ele é muito engraçado."),("She is {{a little}} shy.","Ela é um pouco tímida."),("He is {{too}} lazy to run.","Ele é preguiçoso demais para correr."),("My friend is brave and {{loyal}}.","Meu amigo é corajoso e leal.")],"“It's too hot” significa…",["Está quente, que bom.","Está quente demais.","Está um pouco quente."],1,"Too indica excesso, quase sempre um problema."),
81018:("adjetivo + to + verbo","Use **adjetivo + to + verbo**: *He is easy to live with. This is hard to do.*",[("He is {{easy to live with}}.","Ele é fácil de conviver."),("My room is {{tidy}}.","Meu quarto é arrumado."),("We {{share}} the chores.","Dividimos as tarefas."),("This game is {{hard to play}}.","Este jogo é difícil de jogar.")],"Como dizer “fácil de entender”?",["easy to understand","easy understand","easily to understand"],0,"O molde é adjetivo + to + verbo base."),
81019:("there is / there are","**There is** para um só; **there are** para vários. Pergunta: **Is there…?**",[("{{There is}} a market near here.","Há um mercado perto daqui."),("{{There are}} two shops on the corner.","Há duas lojas na esquina."),("{{Is there}} a bus stop?","Há um ponto de ônibus?"),("Yes, {{there is}}. It's near.","Sim, há. É perto.")],"Complete: “___ three parks in my city.”",["There is","There are","There be"],1,"Three parks é plural: there are."),
81020:("there was / there were","No passado: **there was** (um) e **there were** (vários).",[("{{There was}} a big party.","Houve uma festa grande."),("{{There were}} many boxes.","Havia muitas caixas."),("{{Was there}} a party?","Houve uma festa?"),("No, there {{wasn't}}. It was quiet.","Não. Estava tudo quieto.")],"Qual frase está certa?",["There was two boxes.","There were two boxes.","There is two boxes."],1,"Two boxes é plural e passado: there were."),
81021:("was / were","O passado de *am/is* é **was**; o de *are* é **were**. *I was busy. We were tired.*",[("I {{was}} at work.","Eu estava no trabalho."),("We {{were}} at the park.","Estávamos no parque."),("{{Where were you}} yesterday?","Onde você estava ontem?"),("They {{were}} tired in the evening.","Eles estavam cansados à noite.")],"Complete: “She ___ busy yesterday.”",["was","were","is"],0,"She usa was no passado."),
920003:("used to","**Used to** fala de um hábito do passado que acabou. Depois de **did**, escreva **use to** (sem d): *Did you use to play here?*",[("I {{used to}} live outside.","Eu morava fora."),("I {{didn't use to}} like fruit.","Eu não costumava gostar de fruta."),("{{Did you use to}} play here?","Você costumava brincar aqui?"),("I {{used to}} be very shy.","Eu era muito tímido.")],"Qual pergunta está certa?",["Did you used to run?","Did you use to run?","Do you used to run?"],1,"Com did, o verbo fica sem d: use to."),
81022:("was/were nas perguntas","Para perguntar sobre ontem, o verbo **was/were** vai à frente: *Where were you? Was he at home?*",[("{{Where were you}} last night?","Onde você estava ontem à noite?"),("{{Were you}} alone at home?","Você estava sozinho em casa?"),("Yes, I {{was}}.","Sim, estava."),("No, I {{wasn't}}. I was with Tom.","Não. Eu estava com o Tom.")],"Qual é a resposta curta para “Was he at home?”",["Yes, he was.","Yes, he did.","Yes, he is."],0,"Perguntas com was pedem resposta curta com was."),
81023:("Passado com -ed","Verbos regulares ganham **-ed**: *walk → walked*. Se já termina em e, só **-d**: *like → liked*.",[("We {{visited}} the park.","Visitamos o parque."),("We {{walked}} by the river.","Caminhamos pelo rio."),("She {{cooked}} dinner at home.","Ela cozinhou o jantar em casa."),("I {{liked}} the photos.","Gostei das fotos.")],"Qual é o passado de “like”?",["liked","likeed","liking"],0,"Como termina em e, só se acrescenta -d."),
81024:("Passado irregular","Alguns verbos **mudam por inteiro**: *go → went, see → saw, eat → ate, take → took, fly → flew*. Nunca terminam em -ed.",[("We {{went}} to the park.","Fomos ao parque."),("She {{took}} her umbrella.","Ela pegou o guarda-chuva."),("We {{saw}} a kite in the sky.","Vimos uma pipa no céu."),("The kite {{flew}} very high.","A pipa voou bem alto.")],"Qual é o passado de “eat”?",["eated","ate","eaten"],1,"Eat é irregular: ate."),
81025:("Mais irregulares","Para decorar: *buy → bought, come → came, get → got, have → had, give → gave, make → made*.",[("I {{bought}} a new pen.","Comprei uma caneta nova."),("She {{came}} to class early.","Ela veio cedo para a aula."),("Mia {{gave}} me a book.","A Mia me deu um livro."),("We {{made}} a cake and {{had}} fun.","Fizemos um bolo e nos divertimos.")],"Qual é o passado de “give”?",["gived","gave","given"],1,"Give é irregular: gave."),
81026:("Did + verbo base","No passado, a pergunta usa **Did + sujeito + verbo base**: *Did you pay?* Respostas curtas: *Yes, I did. / No, I didn't.*",[("{{Did you pay}} the bill?","Você pagou a conta?"),("Yes, I {{did}}.","Sim, paguei."),("{{Did she call}} you?","Ela ligou para você?"),("No, she {{didn't call}}.","Não, ela não ligou.")],"Qual está certa?",["Did she called?","Did she call?","Does she called?"],1,"Depois de did o verbo volta ao básico: call."),
81027:("for + duração","**For** + tempo diz quanto algo durou: *I stayed for five days*. Pergunta: **How long did you stay?**",[("I stayed {{for five days}}.","Fiquei cinco dias."),("We traveled {{for two weeks}}.","Viajamos por duas semanas."),("{{How long did you stay}}?","Quanto tempo você ficou?"),("I bought a ticket {{for one hour}}.","Comprei um bilhete de uma hora.")],"Como perguntar “por quanto tempo”?",["How long?","How much long?","What long?"],0,"How long pergunta a duração."),
}
